export const storedResources=['wood','stone','sand','iron','berries','cake'];
export function normalizeCamp(v){return {bedMade:!!v?.bedMade,tentMoved:!!v?.tentMoved,storage:Object.fromEntries(storedResources.map(k=>[k,Math.max(0,Math.min(9999,Math.floor(Number(v?.storage?.[k])||0)))])),gardens:v?.gardens&&typeof v.gardens==='object'?v.gardens:{},rare:{appeared:!!v?.rare?.appeared,tame:!!v?.rare?.tame,feed:Math.max(0,Math.min(2,Number(v?.rare?.feed)||0))}};}
export function transferResource(state,inv,k,n){if(!storedResources.includes(k)||!Number.isInteger(n)||!n)return false;const source=n>0?inv:state.storage,dest=n>0?state.storage:inv,amount=Math.abs(n);if((source[k]||0)<amount)return false;source[k]-=amount;dest[k]=(dest[k]||0)+amount;return true;}
export function gardenAction(state,inv,key,now){const due=state.gardens[key];if(due===undefined){if(!(inv.berries>=2))return 'empty';inv.berries-=2;state.gardens[key]=now+90;return 'planted';}if(now<due)return 'waiting';inv.berries+=6;delete state.gardens[key];return 'harvest';}
export function bakeCake(inv){if(!(inv.berries>=4&&inv.wood>=1))return false;inv.berries-=4;inv.wood--;inv.cake=(inv.cake||0)+1;return true;}
export function respawnPoint(state,blocks){const list=[...blocks.values()];return list.find(b=>b.type==='tent')||(!state.tentMoved&&!state.bedMade?{x:0,z:10}:null)||list.find(b=>b.type==='bed')||{x:0,z:15};}
